package vn.rtr.aeris.integration03;
import java.util.*;import java.lang.reflect.*;
/** Reflection runs the exact prior class (renamed only) and the diagnostic overlay. */
public final class PumpScheduling03Test{
 static List<String> drive(Class<?>c)throws Exception{List<String>trace=new ArrayList<>();ArrayDeque<Runnable>main=new ArrayDeque<>(),done=new ArrayDeque<>();Constructor<?>ctor=null;for(Constructor<?>v:c.getConstructors())if(v.getParameterCount()==3)ctor=v;if(ctor==null)throw new AssertionError();Class<?>[]types=ctor.getParameterTypes();Object scheduler=Proxy.newProxyInstance(c.getClassLoader(),new Class[]{types[0]},(p,m,a)->{trace.add("post");main.add((Runnable)a[0]);return null;}),evaluator=Proxy.newProxyInstance(c.getClassLoader(),new Class[]{types[1]},(p,m,a)->{trace.add("batch:"+a[0]);done.add((Runnable)a[1]);return null;});Object pump=ctor.newInstance(scheduler,evaluator,(java.util.function.Consumer<String>)r->trace.add("failure:"+r));Method enqueue=c.getMethod("enqueue",String.class),out=c.getMethod("outstanding");for(int i=0;i<23;i++)enqueue.invoke(pump,"e"+i);trace.add("out:"+out.invoke(pump));main.remove().run();for(int i=23;i<31;i++)enqueue.invoke(pump,"e"+i);while(!done.isEmpty()){done.remove().run();trace.add("out:"+out.invoke(pump));while(!main.isEmpty())main.remove().run();}for(int i=0;i<65;i++)enqueue.invoke(pump,"overflow"+i);while(!main.isEmpty())main.remove().run();trace.add("failed:"+c.getMethod("failed").invoke(pump));return trace;}
 public static void main(String[]a)throws Exception{List<String>old=drive(Class.forName("vn.rtr.aeris.integration03.OldUiPump98")),current=drive(UiPump98.class);if(!old.equals(current))throw new AssertionError("SCHEDULING_OR_ORDER_CHANGED: "+old+" / "+current);System.out.println("{\"status\":\"PASS\",\"scope\":\"ACTUAL_OLD_RENAMED_ONLY_VS_NEW_UIPUMP\",\"exactScheduleCallbackBatchOrderAndBounds\":true,\"traceEvents\":"+old.size()+"}");}
}
